create extension if not exists pgcrypto;
create table if not exists public.site_settings(key text primary key,value text not null default '');
create table if not exists public.team_members(id uuid primary key default gen_random_uuid(),name text not null,role text default 'Professional Team Member',bio text default '',photo_url text default '',gender_group text default '',created_at timestamptz default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),name text unique not null,description text default '',page_url text default '',image_url text default '',created_at timestamptz default now());
create table if not exists public.insurance_plans(id uuid primary key default gen_random_uuid(),name text unique not null,suitable_for text default '',main_point text default '',sort_order int default 0);
create table if not exists public.leads(id uuid primary key default gen_random_uuid(),name text,zip_code text,age int,state text,coverage_type text,phone text,email text,message text,source_page text,created_at timestamptz default now());
create table if not exists public.consultations(id uuid primary key default gen_random_uuid(),name text,phone text,email text,method text,preferred_date date,preferred_time time,message text,source_page text,created_at timestamptz default now());
alter table public.site_settings enable row level security;
alter table public.team_members enable row level security;
alter table public.services enable row level security;
alter table public.insurance_plans enable row level security;
alter table public.leads enable row level security;
alter table public.consultations enable row level security;
create policy "public read settings" on public.site_settings for select using(true);
create policy "public read team" on public.team_members for select using(true);
create policy "public read services" on public.services for select using(true);
create policy "public read plans" on public.insurance_plans for select using(true);
create policy "public insert leads" on public.leads for insert with check(true);
create policy "public insert consultations" on public.consultations for insert with check(true);
create policy "auth read leads" on public.leads for select to authenticated using(true);
create policy "auth read consultations" on public.consultations for select to authenticated using(true);
create policy "auth manage settings" on public.site_settings for all to authenticated using(true) with check(true);
create policy "auth manage team" on public.team_members for all to authenticated using(true) with check(true);
create policy "auth manage services" on public.services for all to authenticated using(true) with check(true);
create policy "auth manage plans" on public.insurance_plans for all to authenticated using(true) with check(true);

-- Private admin media library. Uploads are accessible only to authenticated admin users.

drop policy if exists "Authenticated users can view site files" on storage.objects;
drop policy if exists "Authenticated users can upload site files" on storage.objects;
drop policy if exists "Authenticated users can update site files" on storage.objects;
drop policy if exists "Authenticated users can delete site files" on storage.objects;

create policy "Authenticated users can view site files" on storage.objects for select to authenticated using (bucket_id = 'site-files');
create policy "Authenticated users can upload site files" on storage.objects for insert to authenticated with check (bucket_id = 'site-files');
create policy "Authenticated users can update site files" on storage.objects for update to authenticated using (bucket_id = 'site-files') with check (bucket_id = 'site-files');
create policy "Authenticated users can delete site files" on storage.objects for delete to authenticated using (bucket_id = 'site-files');
